components.css:
.ds-booking { display: inline-flex; align-items: center; gap: 22px; min-height: 52px; box-sizing: border-box; background: #492f22; color: #fffaf5; border: 0; border-radius: 0; font: 500 15px/1.2 var(--sans, "Golos Text", Arial, sans-serif); padding: 12px 20px; text-decoration: none; transition: background 150ms, transform 150ms var(--ease, cubic-bezier(.22,1,.36,1)); }
.ds-booking svg { flex: none; }
.ds-booking:is(:hover, :focus-visible) { background: #674331; }
.ds-booking:focus-visible { outline: 2px solid var(--accent, #744631); outline-offset: 4px; }
@media (hover: hover) { .ds-booking:hover { transform: translateY(-2px); } }
.ds-booking:active { transform: translateY(1px); }
@media (prefers-reduced-motion: reduce) { .ds-booking { transition: none; } .ds-booking:is(:hover, :active) { transform: none; } }

.ds-inline-action { display: inline-flex; align-items: center; min-height: 44px; color: var(--ink, #39251b); font: 16px/1.55 var(--sans, "Golos Text", Arial, sans-serif); text-decoration: underline; text-underline-offset: 4px; }
.ds-inline-action:hover { color: var(--accent, #744631); }
.ds-inline-action:focus-visible { outline: 2px solid var(--accent, #744631); outline-offset: 4px; }

.ds-nav { display: flex; flex-wrap: wrap; align-items: center; gap: clamp(12px, 2vw, 32px); }
.ds-nav a { display: flex; align-items: center; min-height: 44px; color: var(--ink, #39251b); font: 14px/1.55 var(--sans, "Golos Text", Arial, sans-serif); text-decoration: none; text-underline-offset: 4px; }
.ds-nav a:is(:hover, :focus-visible) { text-decoration: underline; }
.ds-nav a:focus-visible { outline: 2px solid var(--accent, #744631); outline-offset: 4px; }

.ds-mobile-menu { display: grid; justify-items: end; background: #f5e3cc; color: var(--ink, #39251b); }
.ds-mobile-menu summary { display: flex; align-items: center; justify-content: flex-end; list-style: none; min-height: 44px; gap: 11px; padding: 0 3px 0 12px; cursor: pointer; font: 500 15px var(--sans, "Golos Text", Arial, sans-serif); }
.ds-mobile-menu summary::-webkit-details-marker { display: none; }
.ds-mobile-menu summary span { box-sizing: border-box; width: 19px; height: 10px; border-block: 1px solid; transition: transform 150ms; }
.ds-mobile-menu[open] summary span { transform: rotate(90deg); }
.ds-mobile-menu nav { display: grid; border-top: 1px solid var(--rule, #cebaa9); padding: 8px 20px 16px; }
.ds-mobile-menu a { display: flex; align-items: center; min-height: 44px; color: inherit; font: 13px/1.55 var(--sans, "Golos Text", Arial, sans-serif); text-decoration: none; text-underline-offset: 4px; }
.ds-mobile-menu a:is(:hover, :focus-visible) { text-decoration: underline; }
.ds-mobile-menu :is(summary, a):focus-visible { outline: 2px solid var(--accent, #744631); outline-offset: 4px; }
@media (prefers-reduced-motion: reduce) { .ds-mobile-menu summary span { transition: none; } }

.ds-services { color: var(--ink, #39251b); }
.ds-services details { border-top: 1px solid var(--rule, #cebaa9); margin: 0; }
.ds-services details:last-of-type { border-bottom: 1px solid var(--rule, #cebaa9); }
.ds-services summary { box-sizing: border-box; list-style: none; display: flex; gap: 16px; align-items: center; justify-content: space-between; min-height: 56px; padding-block: 8px; cursor: pointer; font: 500 clamp(23px, 2.5vw, 34px)/1 var(--display, "Cormorant Garamond", Georgia, serif); }
.ds-services summary::-webkit-details-marker { display: none; }
.ds-services summary:hover { color: var(--accent, #744631); }
.ds-services summary:focus-visible { outline: 2px solid var(--accent, #744631); outline-offset: 4px; }
.ds-services summary svg { flex: none; transition: transform 150ms var(--ease, cubic-bezier(.22,1,.36,1)); }
.ds-services details[open] summary svg { transform: rotate(45deg); }
.ds-services ul { display: grid; gap: 6px; padding: 0 0 14px; margin: 0; list-style-position: inside; color: var(--muted, #674d40); font: 15px/1.55 var(--sans, "Golos Text", Arial, sans-serif); }
.ds-services details[open] ul { animation: ds-detail-enter 180ms var(--ease, cubic-bezier(.22,1,.36,1)) both; }
@keyframes ds-detail-enter { from { opacity: .7; transform: translateY(-4px); } }
@media (prefers-reduced-motion: reduce) { .ds-services summary svg { transition: none; } .ds-services details[open] ul { animation: none; } }
